//autogenerated:yes
//nolint:revive,govet,errcheck
package development_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
)

func TestEnum_RANGING_BEACON_STATUS_FLAG(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.RANGING_BEACON_STATUS_FLAG
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.RANGING_BEACON_STATUS_FLAG_STATION_SIGNAL_POOR.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.RANGING_BEACON_STATUS_FLAG
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.RANGING_BEACON_STATUS_FLAG_STATION_SIGNAL_POOR, dec)
	})
}
